#include <iostream>
#include <string>
#include <climits>
using namespace std;

// 判断字符是否为小写字母
bool isLower(char c) {
    return c >= 'a' && c <= 'z';
}

int solve(const string& s) {
    string target = "AcMer";
    int ans = INT_MAX;

    // 枚举所有长度为5的子串
    for (int i = 0; i <= (int)s.size() - 5; ++i) {
        int cost = 0;
        for (int j = 0; j < 5; ++j) {
            char cur = s[i + j];
            char tar = target[j];
            if (cur == tar) continue;

            // 判断大小写属性是否相同
            if (isLower(cur) == isLower(tar)) {
                cost += 5;   // 大小写相同，仅换字母
            } else {
                cost += 6;   // 大小写不同
            }
        }
        ans = min(ans, cost);
    }
    return ans;
}

int main() {
    string s;
    cin >> s;
    cout << solve(s) << endl;
    return 0;
}
